"""Plain-language terms; build.py adds links and writes static glossary HTML."""
TERMS = [
 ('eval','Eval','A defined procedure for measuring a system on tasks using specified scoring rules.'),
 ('estimand','Estimand','The exact population quantity you want to estimate, including the population, run policy, score, and weighting.'),
 ('estimate','Estimate','A number calculated from observed data to learn about an estimand.'),
 ('population','Population','The tasks, attempts, users, or other units to which a stated result is meant to apply.'),
 ('sample','Sample','The units actually observed under a stated selection process.'),
 ('sampling-frame','Sampling frame','The accessible list or process from which a sample can be selected; it may omit parts of the target population.'),
 ('denominator','Denominator','The count or weight being divided by. Changing it can change the question a rate answers.'),
 ('percentage-point','Percentage point','An absolute difference between percentages: 72% to 78% is six percentage points.'),
 ('mean','Mean','Sum of the values divided by their count; a binary mean is the fraction of passes.'),
 ('median','Median','A central ordered value; for an even count, this course averages the two central values.'),
 ('quantile','Quantile','A value locating a stated fraction of a distribution; sample quantiles require a specified interpolation convention.'),
 ('outlier','Outlier','An observation unusually far from others; investigate its origin before deciding whether it belongs in the analysis.'),
 ('random-variable','Random variable','A numeric quantity whose value depends on an uncertain outcome.'),
 ('probability','Probability','A number between zero and one describing uncertainty about an event under a model.'),
 ('conditional-probability','Conditional probability','The probability of an event after restricting attention to a stated condition.'),
 ('independence','Independence','A property under which learning one outcome does not change the probability distribution of another.'),
 ('bernoulli','Bernoulli','A distribution for a binary outcome: one with probability p, zero otherwise.'),
 ('binomial','Binomial','The distribution of the number of successes in a fixed number of independent Bernoulli trials sharing one success probability.'),
 ('expectation','Expectation','A probability-weighted average of possible values; it need not itself be an outcome.'),
 ('variance','Variance','Average squared distance from an expectation; sample variance uses an estimated center and usually divides by n−1.'),
 ('standard-deviation','Standard deviation','The square root of variance; it describes spread on the original measurement scale.'),
 ('standard-error','Standard error','The standard deviation of an estimator over repetitions of the stated sampling process; usually estimated from the observed data.'),
 ('bias','Bias','A systematic discrepancy. Estimator bias means its expected value differs from its target; measurement or selection bias can change the target being measured.'),
 ('confidence-interval','Confidence interval','An interval from a procedure designed to cover a fixed target at a stated long-run rate under its assumptions.'),
 ('coverage','Coverage','The probability that an interval-producing procedure contains its target over repetitions of the specified experiment.'),
 ('wilson-interval','Wilson interval','A score-test interval for a binomial proportion whose endpoints remain in the allowable zero-to-one range.'),
 ('bootstrap','Bootstrap','Approximate sampling variation by drawing new samples with replacement from observed independent units and recomputing the statistic.'),
 ('monte-carlo-error','Monte Carlo error','Numerical uncertainty caused by using finitely many random simulations; distinct from uncertainty due to having limited evaluation data.'),
 ('paired-comparison','Paired comparison','An analysis that retains the relationship between measurements on the same task or matched unit.'),
 ('covariance','Covariance','A measure of whether two quantities tend to vary together; it enters the variance of their difference.'),
 ('effect-size','Effect size','The magnitude of a difference or relationship on a specified scale, such as percentage points.'),
 ('null-hypothesis','Null hypothesis','A specified statistical claim against which a test evaluates compatibility, often no average change.'),
 ('p-value','P-value','Under a specified null model, the probability of a test statistic at least as extreme as observed, using the stated direction or tail rule.'),
 ('type-i-error','Type I error','Rejecting a true null hypothesis; a test’s alpha aims to limit this frequency under its assumptions.'),
 ('type-ii-error','Type II error','Failing to reject a null when a specified alternative is true.'),
 ('power','Power','The probability a test rejects its null under a particular alternative and experimental design.'),
 ('minimum-detectable-effect','Minimum detectable effect','The effect a planned design can detect with stated power and error threshold under its assumptions.'),
 ('noninferiority','Noninferiority','A claim that a candidate’s loss is smaller than a predeclared acceptable margin, supported by an appropriate one-sided analysis.'),
 ('equivalence','Equivalence','Evidence that a difference lies within predeclared lower and upper practical margins; failure to reject zero does not establish it.'),
 ('cluster','Cluster','A group of observations that can share dependence, such as tasks from one repository.'),
 ('pseudoreplication','Pseudoreplication','Treating dependent observations as independent evidence about a population.'),
 ('stratum','Stratum','A defined population subgroup sampled or analyzed separately, such as a language or task category.'),
 ('macro-average','Macro-average','An average that gives equal weight to groups, rather than weighting by each group’s observation count.'),
 ('micro-average','Micro-average','An aggregate formed by pooling the underlying contributions, such as total correct divided by total attempted.'),
 ('distribution-shift','Distribution shift','A change in the population or conditions between evaluation and the use to which its results are applied.'),
 ('confounding','Confounding','Mixing the effect of interest with other differences, so the comparison cannot isolate the claimed cause.'),
 ('censoring','Censoring','Partial observation of a value, such as knowing runtime exceeded a timeout without observing its eventual duration.'),
 ('confusion-matrix','Confusion matrix','Counts crossing reference labels with predicted labels, exposing true and false positives and negatives.'),
 ('precision','Precision','Among predicted positive cases, the fraction actually positive according to the reference labels; distinct from statistical precision of an estimator.'),
 ('recall','Recall','Among reference-positive cases, the fraction correctly detected; also called sensitivity.'),
 ('specificity','Specificity','Among reference-negative cases, the fraction correctly predicted negative.'),
 ('prevalence','Prevalence','The proportion of positive cases in a specified population; here often the failure rate.'),
 ('calibration','Calibration','Agreement between stated probabilities and observed event frequencies on the relevant population.'),
 ('brier-score','Brier score','The average squared difference between a forecast probability and a binary outcome; lower is better.'),
 ('prior','Prior','A probability distribution expressing uncertainty about a parameter before the analyzed data.'),
 ('likelihood','Likelihood','The probability or density of the observed data viewed as a function of a model parameter.'),
 ('posterior','Posterior','A parameter distribution after updating a prior with a likelihood and observed data.'),
 ('credible-interval','Credible interval','An interval containing a specified amount of posterior probability under the chosen model and prior.'),
 ('familywise-error','Familywise error','The probability of at least one false rejection in a specified family of hypotheses.'),
 ('false-discovery-rate','False discovery rate','The expected fraction of false rejections among rejections, with the fraction defined as zero if nothing is rejected.'),
 ('optional-stopping','Optional stopping','Choosing when to stop from observed results; valid inference must account for the rule used.'),
 ('confidence-sequence','Confidence sequence','A sequence of intervals designed for simultaneous coverage across the permitted observation times under stated assumptions.'),
 ('holdout','Holdout','Data reserved for evaluation after choices have been fixed; repeatedly tuning against it spends its independence.'),
 ('pass-at-k','Pass@k','The probability at least one of k attempts succeeds on a task, averaged over tasks under a specified sampling policy.'),
 ('all-k-success','All-k success','The probability every one of k attempts succeeds on a task, averaged over tasks; sometimes written pass^k.'),
 ('pareto-frontier','Pareto frontier','Choices for which no other available choice is at least as good on every stated objective and better on at least one.'),
]
GLOSSARY = {slug:dict(name=name, short=definition, defn=definition) for slug,name,definition in TERMS}
